-- ============================================================================
-- Smart Parking Management System — MySQL 8 seed data
-- Run AFTER database/schema.sql:
--   mysql -u root -p smart_parking < database/schema.sql
--   mysql -u root -p smart_parking < database/seed.sql
--
-- Demo accounts (passwords are BCrypt-hashed in users.password_hash):
--   ADMIN  admin@smartparking.local / admin123
--   USER   user1@example.com        / user123
--   USER   user2@example.com        / user123
--
-- Dates are relative (CURDATE()/NOW()) so "today" and the past-7-days history
-- are always current whenever the seed is loaded.
-- ============================================================================

SET NAMES utf8mb4;

-- ---------------------------------------------------------------- users

-- ---------------------------------------------------------------- locations

SET @loc1 = (SELECT id FROM parking_locations WHERE name = 'KL University Main Gate Parking');
SET @loc2 = (SELECT id FROM parking_locations WHERE name = 'City Center Mall Parking');
SET @u1 = (SELECT id FROM users WHERE email = 'user1@example.com');
SET @u2 = (SELECT id FROM users WHERE email = 'user2@example.com');

-- ---------------------------------------------------------------- slots (16 per location)

-- ---------------------------------------------------------------- vehicles

SET @v1 = (SELECT id FROM vehicles WHERE license_plate = 'TS09AB1234');
SET @v2 = (SELECT id FROM vehicles WHERE license_plate = 'TS09CD5678');
SET @v3 = (SELECT id FROM vehicles WHERE license_plate = 'TS08EF9012');
SET @v4 = (SELECT id FROM vehicles WHERE license_plate = 'TS07GH3456');


-- ---------------------------------------------------------------- reservations: today
-- OCCUPIED right now
(@u1, @v1, (SELECT id FROM parking_slots WHERE location_id = @loc1 AND slot_code = 'A-01'), DATE_SUB(NOW(), INTERVAL 1 HOUR), DATE_ADD(NOW(), INTERVAL 2 HOUR), 'OCCUPIED', 90.00, DATE_SUB(NOW(), INTERVAL 50 MINUTE), NULL, NOW(), NOW()),
(@u2, @v3, (SELECT id FROM parking_slots WHERE location_id = @loc2 AND slot_code = 'B-01'), DATE_SUB(NOW(), INTERVAL 2 HOUR), DATE_ADD(NOW(), INTERVAL 1 HOUR), 'OCCUPIED', 150.00, DATE_SUB(NOW(), INTERVAL 110 MINUTE), NULL, NOW(), NOW()),
-- RESERVED later today
(@u1, @v2, (SELECT id FROM parking_slots WHERE location_id = @loc1 AND slot_code = 'A-05'), DATE_ADD(NOW(), INTERVAL 2 HOUR), DATE_ADD(NOW(), INTERVAL 4 HOUR), 'RESERVED', 60.00, NULL, NULL, NOW(), NOW()),
(@u2, @v4, (SELECT id FROM parking_slots WHERE location_id = @loc2 AND slot_code = 'B-06'), DATE_ADD(NOW(), INTERVAL 1 HOUR), DATE_ADD(NOW(), INTERVAL 3 HOUR), 'RESERVED', 100.00, NULL, NULL, NOW(), NOW()),
(@u1, @v1, (SELECT id FROM parking_slots WHERE location_id = @loc1 AND slot_code = 'A-09'), DATE_ADD(NOW(), INTERVAL 3 HOUR), DATE_ADD(NOW(), INTERVAL 5 HOUR), 'RESERVED', 60.00, NULL, NULL, NOW(), NOW()),
-- COMPLETED earlier today
(@u2, @v3, (SELECT id FROM parking_slots WHERE location_id = @loc1 AND slot_code = 'A-03'), TIMESTAMP(CURDATE(),'07:00:00'), TIMESTAMP(CURDATE(),'09:00:00'), 'COMPLETED', 60.00, TIMESTAMP(CURDATE(),'07:05:00'), TIMESTAMP(CURDATE(),'08:55:00'), TIMESTAMP(CURDATE(),'06:50:00'), TIMESTAMP(CURDATE(),'08:55:00')),
(@u1, @v1, (SELECT id FROM parking_slots WHERE location_id = @loc2 AND slot_code = 'B-04'), TIMESTAMP(CURDATE(),'08:00:00'), TIMESTAMP(CURDATE(),'10:00:00'), 'COMPLETED', 100.00, TIMESTAMP(CURDATE(),'08:02:00'), TIMESTAMP(CURDATE(),'09:50:00'), TIMESTAMP(CURDATE(),'07:45:00'), TIMESTAMP(CURDATE(),'09:50:00'));


-- ---------------------------------------------------------------- reservations: past 7 days (history for dashboard + prediction)

-- ============================================================================
-- v3 seed: pricing columns backfill, promo codes, payments, reviews
-- ============================================================================

-- Seeded bookings predate surge/promo pricing: base = fee, multiplier 1.00, no discount.
UPDATE reservations SET base_amount = fee_amount, pricing_multiplier = 1.00, discount_amount = 0.00;


-- One payment row per reservation: COMPLETED / OCCUPIED are PAID, RESERVED stays PENDING.
SELECT id, fee_amount, 'PAID', 'SIMULATED_CARD', CONCAT('TXN-SEED', LPAD(id, 4, '0')), exit_time
FROM reservations WHERE status = 'COMPLETED';

SELECT id, fee_amount, 'PAID', 'SIMULATED_CARD', CONCAT('TXN-SEED', LPAD(id, 4, '0')), entry_time
FROM reservations WHERE status = 'OCCUPIED';

SELECT id, fee_amount, 'PENDING'
FROM reservations WHERE status = 'RESERVED';

-- Reviews on COMPLETED reservations (one per reservation): 2 per location.
SELECT r.id, r.user_id, s.location_id, 5, 'Smooth entry, clean and well-lit bays.'
FROM reservations r JOIN parking_slots s ON s.id = r.slot_id
WHERE r.status = 'COMPLETED' AND s.location_id = @loc1
ORDER BY r.start_time LIMIT 1;

SELECT r.id, r.user_id, s.location_id, 4, 'Good experience overall, fills up fast in the evening.'
FROM reservations r JOIN parking_slots s ON s.id = r.slot_id
WHERE r.status = 'COMPLETED' AND s.location_id = @loc1
  AND r.id NOT IN (SELECT reservation_id FROM reviews)
ORDER BY r.start_time LIMIT 1;

SELECT r.id, r.user_id, s.location_id, 4, 'Convenient location, easy exit.'
FROM reservations r JOIN parking_slots s ON s.id = r.slot_id
WHERE r.status = 'COMPLETED' AND s.location_id = @loc2
ORDER BY r.start_time LIMIT 1;

SELECT r.id, r.user_id, s.location_id, 5, 'Plenty of EV slots, will use again.'
FROM reservations r JOIN parking_slots s ON s.id = r.slot_id
WHERE r.status = 'COMPLETED' AND s.location_id = @loc2
  AND r.id NOT IN (SELECT reservation_id FROM reviews)
ORDER BY r.start_time LIMIT 1;
